  architecture:['spring','owasp'],context:['owasp'],rag:['owaspRag','selfrag'],tools:['mcp','owaspAgent'],jwt:['jwt','spring'],idempotency:['http'],outbox:['http'],resilience:['resilience','http'],observability:['otel'],evals:['selfrag','nist'],security:['owasp','owaspRag'],performance:['cache','http'],inbox:['http'],optimistic:['jpa'],upsert:['postgres'],saga:['http'],angular:['angular'],'self-rag':['selfrag','owaspRag'],'ai-foundations':['googleMl','nist'],'supervised-learning':['googleMl'],'neural-networks':['pytorch'],transformers:['hf'],embeddings:['owaspRag','selfrag'],'agents-mcp':['mcp','owaspAgent'],multimodal:['owasp'],'fine-tuning':['googleMl','mlflow'],mlops:['mlflow','otel'],'ai-governance':['nist'],'ai-evals':['nist','selfrag'],'ai-capstone':['spring','angular','nist']
