const baseDoc=doc,baseBind=bind;doc=l=>{const q=quizzes[l.id];return baseDoc(l)+`<section class="callout" style="margin-top:18px;border-left-color:var(--lime)"><strong>Mini-reto.</strong><p style="margin:7px 0 12px">${q.q}</p><div>${q.a.map((a,i)=>`<button class="next-button" style="margin:0 7px 7px 0" data-quiz="${i}">${a}</button>`).join('')}</div><p id="quiz-result" style="margin:7px 0 0"></p></section>`};
