function setupSearch(){
  const overlay=document.createElement('div');
  overlay.className='search-overlay';overlay.id='search-overlay';overlay.setAttribute('aria-hidden','true');
  overlay.innerHTML='<section class="search-dialog" role="dialog" aria-modal="true" aria-labelledby="search-title"><div class="search-top"><input id="lesson-search-input" type="search" autocomplete="off" placeholder="Buscar RAG, idempotencia, Angular, caso…" aria-label="Buscar en el laboratorio"><button class="search-close" type="button" aria-label="Cerrar búsqueda">Esc</button></div><div class="search-hint"><span id="search-title">BUSCADOR DEL LABORATORIO</span><span>⌘/Ctrl + K para abrir</span></div><div class="search-results" id="search-results"></div></section>';
  document.body.append(overlay);
  const input=overlay.querySelector('#lesson-search-input'),results=overlay.querySelector('#search-results'),close=overlay.querySelector('.search-close');
  const searchText=l=>{const c=teachingCases[l.id]||{};return [l.file,l.title,l.tag,l.lead,l.concept.join(' '),l.choice,l.risks,l.check,l.code,c.title,c.context,c.decision,c.evidence].join(' ').toLowerCase()};
  const render=query=>{const normalized=query.trim().toLowerCase();const matches=normalized?lessons.filter(l=>searchText(l).includes(normalized)):lessons.slice(0,8);results.innerHTML='';if(!matches.length){const empty=document.createElement('p');empty.className='search-empty';empty.textContent='No hay coincidencias todavía. Probá con un patrón, tecnología o problema de negocio.';results.append(empty);return}matches.forEach(l=>{const c=teachingCases[l.id]||{};const button=document.createElement('button');button.type='button';button.className='search-result';const marker=document.createElement('span');marker.textContent=l.tag;const copy=document.createElement('div');const title=document.createElement('b');title.textContent=l.file+' · '+l.title;const summary=document.createElement('small');summary.textContent=normalized?(c.title?'Caso: '+c.title+' — ':'')+l.lead:'Módulo '+(lessons.indexOf(l)+1)+' · '+(c.title?'Caso: '+c.title:l.lead);copy.append(title,summary);button.append(marker,copy);button.onclick=()=>{hide();select(l.id);document.querySelector('.document').scrollTo?.(0,0);log('Búsqueda abrió: '+l.file,'good')};results.append(button)})};
  const show=()=>{overlay.classList.add('visible');overlay.setAttribute('aria-hidden','false');render(input.value);setTimeout(()=>input.focus(),0)};
  const hide=()=>{overlay.classList.remove('visible');overlay.setAttribute('aria-hidden','true')};
  input.oninput=()=>render(input.value);close.onclick=hide;overlay.onclick=e=>{if(e.target===overlay)hide()};
  document.querySelector('[aria-label="Búsqueda"]').onclick=show;
  document.addEventListener('keydown',e=>{if((e.metaKey||e.ctrlKey)&&e.key.toLowerCase()==='k'){e.preventDefault();show()}if(e.key==='Escape'&&overlay.classList.contains('visible'))hide()});
}
