  service:{path:'backend/src/main/java/com/reeb/llmstudio/learning',file:'LearningService.java',lang:'Java · Spring Service',role:'Reglas de aprendizaje y progreso persistente',pattern:'Service + transacción: el controlador no sabe cómo se guarda ni valida la respuesta.',definition:'El servicio siembra módulos, expone el progreso y valida respuestas. @Transactional delimita una operación de negocio.',trace:['PUT /api/progress','LearningController.complete()','LearningService.complete()','ProgressRepository.save()','Progreso actualizado'],code:['@Service','@Transactional','public class LearningService {','  private final ProgressRepository progress;','','  public LearningDtos.ProgressResponse complete(','      LearningDtos.CompleteModuleRequest request) {','    var item = progress.findByLearnerIdAndModuleId(','      request.learnerId(), request.moduleId())','      .orElseGet(() -> new LearningProgress(','        request.learnerId(), request.moduleId(), false));','    item.complete();','    progress.save(item);','    return progress(request.learnerId());','  }','}'].join('\n')},
  module:{path:'backend/src/main/java/com/reeb/llmstudio/learning',file:'LearningModule.java',lang:'Java · JPA Entity',role:'Entidad persistente de un módulo del laboratorio',pattern:'Entidad JPA: el modelo de dominio es distinto del DTO que devuelve la API.',definition:'Una entidad tiene identidad y ciclo de vida de persistencia. El DTO evita exponerla directamente al frontend.',trace:['Arranque de Spring','LearningService.seed()','LearningModule creado','ModuleRepository.save()','H2 persiste el módulo'],code:['@Entity','@Table(name = "learning_modules")','public class LearningModule {','  @Id','  private String id;','  private String title;','  private String category;','  private int position;','','  protected LearningModule() {}','  public LearningModule(String id, String title,','      String category, int position) {','    this.id = id;','    this.title = title;','    this.category = category;','    this.position = position;','  }','}'].join('\n')},
