  selfrag:{path:'backend/src/main/java/com/reeb/llmstudio/learning',file:'SelfRagVerifier.java',lang:'Java · Spring Service',role:'Verifica citas antes de publicar una respuesta RAG',pattern:'Crítica determinista: el verificador no adivina verdad semántica; comprueba evidencia disponible y referencias válidas.',definition:'Si no hay evidencia, faltan citas o una cita no fue recuperada, devuelve evidence-fallback. Así el modelo no transforma texto probable en una afirmación sin soporte.',trace:['POST /api/self-rag/review','LearningService.reviewSelfRag()','SelfRagVerifier.review()','Citas vs. evidencia recuperada','Grounded o evidence-fallback'],code:['@Service','public class SelfRagVerifier {','  public SelfRagReviewResponse review(Request request) {','    Set<String> available = evidenceIds(request.evidence());','    if (available.isEmpty()) return fallback(\"Sin evidencia\");','    if (request.citations().isEmpty()) return fallback(\"Sin citas\");','    if (!available.containsAll(request.citations())) {','      return fallback(\"Cita fuera del retrieval\");','    }','    return grounded(request.answer(), request.citations());','  }','}'].join('\n')},
  app:{path:'frontend/src/app',file:'app.ts',lang:'TypeScript · Angular Signals',role:'Estado de UI, carga de datos y respuesta al reto',pattern:'Component + Signals: el estado visible tiene nombres explícitos y se actualiza desde la API.',definition:'signal() guarda estado reactivo local. Cuando llega la API, el componente actualiza módulos y progreso.',trace:['Usuario elige respuesta','App.answer(index)','LearningApi.validate()','API valida contrato','App.complete() guarda progreso'],code:['export class App {','  private readonly api = inject(LearningApi);','  protected readonly modules = signal<LearningModule[]>([]);','  protected readonly completed = signal<Set<string>>(new Set());','  protected readonly selected = signal<LearningModule | null>(null);','','  protected answer(index: number): void {','    const module = this.selected();','    if (!module) return;','    this.api.validate(module.id, index).subscribe({','      next: result => {','        this.feedback.set(result.feedback);','        if (result.correct) this.complete(module.id);','      }','    });','  }','}'].join('\n')},
  api:{path:'frontend/src/app',file:'learning-api.ts',lang:'TypeScript · Angular HttpClient',role:'Cliente tipado que conecta Angular con Spring',pattern:'API service: una sola frontera para contratos HTTP; los componentes no arman URLs ni payloads.',definition:'LearningModule documenta el contrato esperado. El servicio devuelve observables para modelar carga, éxito y error.',trace:['App.load()','LearningApi.modules()','GET /api/modules','Spring devuelve ModuleResponse[]','Signal modules actualizada'],code:['@Injectable({ providedIn: "root" })','export class LearningApi {','  private readonly http = inject(HttpClient);','  private readonly baseUrl = "http://localhost:8080/api";','','  modules() {','    return this.http.get<LearningModule[]>(','      this.baseUrl + "/modules");','  }','','  validate(moduleId: string, selectedOption: number) {','    return this.http.post<ChallengeResult>(','      this.baseUrl + "/challenges/validate",','      { moduleId, selectedOption });','  }','}'].join('\n')},
